"""Parcours progressif : contenus pédagogiques et notation écrite pour ténor Si♭."""
import json,re
from music_theory import KEYS,QUALITIES,SCALES,scale,spell,pretty,french,concert,chord,cadence,notes_text,study_grid

def build_progression(env):
    table,call,sec,ex,page,shell=[env[k] for k in ('table','call','sec','exercise','render_page','shell')]
    out=env['OUT'];chapters=env['chapters'];old=env['legacy_lessons']
    def chords_table(chords):
        return table(['Accord écrit pour ténor','Notes écrites : français (anglo-saxon)','Tierce / septième ou sixte'],[[c['symbol'],notes_text(c['notes']),french(c['notes'][1])+' / '+french(c['notes'][3])] for c in chords])
    def cadence_table(root,mode):return chords_table(cadence(root,mode))
    def ready(text):return call('Avant de poursuivre',text)
    def original_grid(grid):
        rows=[]
        for m in grid:
            symbols=' · '.join(c['symbol']+f" ({c['beats']} t.)" for c in m['chords'])
            rows.append([str(m['number']),m['section'],symbols])
        return table(['Mesure','Section','Accords écrits et durées'],rows)
    def form_diagram(grid):
        from html import escape
        svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 820 340" role="img"><title>Étude originale AABA : trente-deux mesures en notation ténor Si bémol</title><rect width="820" height="340" rx="20" fill="#f7f8f2"/>'
        for row,label in enumerate(['A₁','A₂','B','A₃']):
            y=25+row*77
            svg+=f'<text x="24" y="{y+34}" text-anchor="middle" font-family="sans-serif" font-size="17" fill="#275c47">{label}</text>'
            for col in range(8):
                m=grid[row*8+col];x=54+col*94
                colour='#faf0e6' if row==2 else '#edf2e7'
                if m['chords'][-1]['quality']=='maj7' and m['chords'][-1]['root']=='Eb':colour='#ddf18a'
                svg+=f'<rect x="{x}" y="{y}" width="87" height="63" rx="10" fill="{colour}" stroke="#cdd8c5"/><text x="{x+9}" y="{y+15}" font-family="sans-serif" font-size="10" fill="#65746b">{m["number"]}</text>'
                for j,c in enumerate(m['chords']):
                    text=escape(c['symbol']);size=12 if len(m['chords'])<3 else 10
                    svg+=f'<text x="{x+43}" y="{y+31+j*13}" text-anchor="middle" font-family="sans-serif" font-size="{size}" fill="#203b36">{text}</text>'
        return svg+'</svg>'
    def explorer(mode):
        opts=''.join(f'<option value="{k}"'+(' selected' if k==('C' if mode=='minor' else 'Eb') else '')+f'>{french(k)} ({pretty(k)})</option>' for k in KEYS)
        return f'''<div class="tool" id="cadence-tool" data-mode="{mode}"><p class="eyebrow">Atelier de cadences · notation ténor Si♭</p><div class="controls"><label for="cadence-key">Tonique écrite <select id="cadence-key">{opts}</select></label><label for="cadence-mode">Mode <select id="cadence-mode"><option value="major" {'selected' if mode=='major' else ''}>Majeur</option><option value="minor" {'selected' if mode=='minor' else ''}>Mineur</option></select></label></div><h3 id="cadence-heading">II–V–I</h3><div id="cadence-cards" class="cadence"></div><div id="cadence-details"></div><p id="cadence-concert" class="mini"></p><div class="actions"><button class="btn primary" id="cadence-play">Écouter les arpèges pour ténor</button><button class="btn" id="cadence-stop">Arrêter</button></div><p id="cadence-status" class="player-status" aria-live="polite">Une mesure par accord à 60 à la noire. Le son correspond au ténor : une neuvième majeure sous les notes écrites.</p><noscript>Les notes des cadences sont également données dans les tableaux de ce chapitre.</noscript></div>'''
    # 01 — Établir la convention avant tout calcul d'accord.
    tenor=[
    sec('objectif','Objectif & résumé général','<p>Lire une grille destinée au saxophone ténor en Si♭ et savoir la relier à un piano ou à un accompagnement. Tous les accords et toutes les notes de travail du parcours sont <b>écrits pour le ténor</b>. Les sons réels portent explicitement la mention « concert ».</p>'+call('Instrument en Si♭, tonalités multiples','« En Si♭ » décrit la transposition du saxophone. Cela ne signifie pas que tous les morceaux sont en Si♭ majeur. Le ténor joue dans les douze tonalités.')),
    sec('regle','Ce qui est écrit et ce qui sonne','<p>Un Do écrit au ténor produit un Si♭ concert situé une neuvième majeure plus bas : une octave plus un ton. Pour les noms d’accords, on peut se concentrer sur le ton de différence.</p><div class="formula">Écrit ténor → concert : descendre d’un ton<br>Concert → écrit ténor : monter d’un ton</div>'+table(['Écrit pour ténor','Son réel concert'],[['Do (C)','Si♭ (B♭)'],['Ré (D)','Do (C)'],['Mi♭ (E♭)','Ré♭ (D♭)'],['Fa (F)','Mi♭ (E♭)'],['Sol (G)','Fa (F)'],['La (A)','Sol (G)'],['Si (B)','La (A)']])+'<p>Exemple de registre : Do4 écrit, le Do central en convention internationale, sonne Si♭2 concert. Les chiffres d’octave ne seront ajoutés que lorsqu’ils servent le travail du registre.</p><p class="source-note">Le principe de l’instrument transpositeur est présenté dans le <a href="https://www.yamaha.com/en/musical_instrument_guide/saxophone/play/play003.html">guide du saxophone Yamaha</a>.</p>'),
    sec('accords','Transposer un accord entier',table(['Accords écrits pour ténor','Même harmonie en concert'],[['Dm7 → G7 → Cmaj7','Cm7 → F7 → B♭maj7'],['Fm7 → B♭7 → E♭maj7','E♭m7 → A♭7 → D♭maj7'],['Dm7♭5 → G7 → Cm7','Cm7♭5 → F7 → B♭m7']])+'<p>La fondamentale change de nom, mais la qualité de l’accord reste la même. Ainsi, G7 écrit devient F7 concert : il reste un accord de dominante. Tous ses composants se transposent aussi : Sol–Si–Ré–Fa écrits donnent Fa–La–Do–Mi♭ concert.</p>'+call('Repère du parcours','« Body and Soul » est étudié en Mi♭ majeur écrit pour ténor, correspondant à Ré♭ majeur concert. Cette convention est utilisée dans les exercices ; on ne transpose pas une seconde fois une partie déjà destinée au ténor.')),
    sec('accompagnement','Choisir un accompagnement compatible','<p>Pour une cadence Fm7 → B♭7 → E♭maj7 lue au ténor, le piano doit jouer E♭m7 → A♭7 → D♭maj7 en sons réels. Annoncez les deux repères : « Mi♭ écrit ténor, Ré♭ concert ».</p><p>Les lecteurs du cours affichent les notes écrites et produisent les sons réels du ténor. Un clavier dessiné sert à repérer les noms écrits ; il ne représente pas les touches qu’un pianiste doit enfoncer pour accompagner.</p>'),
    sec('exercices','Trois vérifications',ex('1.1','Un nom de note, deux repères','Passer de l’écrit au concert.','Ton et demi-ton.','Donnez les sons réels de Do, Fa et Mi♭ écrits pour ténor. Travaillez les noms de notes sans préciser le registre.','Trois correspondances.','Chaque nom descend d’un ton.',('Un ton contient deux demi-tons.','Do écrit donne Si♭ concert.'),'Do → Si♭ ; Fa → Mi♭ ; Mi♭ → Ré♭. La différence de registre est une neuvième majeure pour les hauteurs exactes.')+ex('1.2','La bonne grille pour le piano','Distinguer les deux conventions.','Règle de transposition.','La grille ténor indique Dm7 → G7 → Cmaj7. Écrivez les accords à transmettre au pianiste. Gardez les qualités.','Une ligne explicitement marquée « concert ».','La ligne est Cm7 → F7 → B♭maj7.',('Transposez les fondamentales, puis recopiez m7, 7, maj7.','Ré devient Do ; Sol devient Fa.'),'Concert : Cm7 → F7 → B♭maj7. Le degré des accords dans leur tonalité sera expliqué au chapitre des cadences.')+ex('1.3','Éviter une double transposition','Préparer une répétition.','Lecture écrit/concert.','Un accompagnement est annoncé en Ré♭ majeur concert. Deux grilles sont proposées : l’une en Ré♭, l’autre déjà marquée « ténor Si♭ » en Mi♭. Choisissez et justifiez sans la transposer à nouveau.','Le choix et une justification de deux phrases.','La partie de ténor en Mi♭ est utilisée telle quelle.',('Le mot « ténor » indique la destination de la partie.','L’accompagnement reste en Ré♭ concert.'),'La grille en Mi♭ déjà écrite pour ténor est la bonne. La monter encore d’un ton donnerait une erreur de transposition.')),
    sec('revision','Fiche de révision',ready('Nommer la tonalité écrite et la tonalité concert, puis expliquer pourquoi une partie déjà transposée se lit telle quelle.')+'<p><b>Erreurs fréquentes.</b> Confondre instrument en Si♭ et tonalité de Si♭ ; transposer les fondamentales sans les autres notes ; transposer deux fois une grille ténor.</p><p><b>Résumé final.</b> Le parcours se lit au ténor. Les sons réels sont distincts. Pour les noms de notes, l’écrit est un ton au-dessus du concert.</p>')]
    page('tenor',tenor)
    # 02 — Notes et degrés, avant le vocabulaire d'accords.
    bases=[old['bases'][0],old['bases'][1],old['bases'][2]]
    bases[0]=sec('objectif','Objectif & résumé général','<p>Nommer les notes, calculer les écarts et retrouver un degré. Les noms sont écrits pour le ténor Si♭. Le but est de comprendre comment se construisent gammes puis accords, sans mémoriser une grille sans repères.</p>')
    bases += [sec('intervalles','Tierce, quinte et octave',table(['Intervalle depuis Do','Demi-tons','Note écrite'],[['Tierce mineure','3','Mi♭ (E♭)'],['Tierce majeure','4','Mi (E)'],['Quinte diminuée','6','Sol♭ (G♭)'],['Quinte juste','7','Sol (G)'],['Octave','12','Do (C), plus aigu']])+'<p>Le nombre de lettres compte aussi : une tierce va de Do à une forme de Mi ; une quinte, de Do à une forme de Sol. Fa♯ et Sol♭ ont la même hauteur sur un clavier, mais n’expriment pas le même intervalle depuis Do.</p>'),sec('degres','Une position dans une gamme','<p>Un degré est une place comptée depuis la tonique. En Mi♭ majeur écrit : I = Mi♭, II = Fa, III = Sol, IV = La♭, V = Si♭, VI = Do, VII = Ré. Ces chiffres serviront à décrire des fonctions indépendantes de la tonalité.</p>'+call('Degré et intervalle','« II » désigne la deuxième place de la gamme ; « deux demi-tons » décrit un écart précis. Dans une gamme majeure, la deuxième note se trouve deux demi-tons au-dessus de la tonique.')),
    sec('exercices','Calculer puis vérifier',ex('2.1','Retrouver les notes','Lire les degrés de Mi♭ majeur.','Ordre des notes.','Écrivez Mi♭ majeur, puis entourez II, V et I. Ne formez pas encore d’accords.','Une gamme avec trois repères.','Fa, Si♭ et Mi♭ sont identifiés.',('La gamme compte sept notes avant l’octave.','Son armure contient Si♭, Mi♭ et La♭.'),'Mi♭ Fa Sol La♭ Si♭ Do Ré. II = Fa, V = Si♭, I = Mi♭.')+ex('2.2','Deux tierces différentes','Calculer des intervalles.','Demi-tons.','Depuis Do, écrivez la tierce mineure, la tierce majeure et la quinte juste. Donnez le nombre de demi-tons.','Trois notes avec leur distance.','Mi♭ = 3, Mi = 4, Sol = 7 demi-tons.',('Comptez les touches voisines sans compter la note de départ.','Une tierce depuis Do porte toujours la lettre Mi.'),'Tierce mineure : Mi♭, 3 demi-tons. Tierce majeure : Mi, 4. Quinte juste : Sol, 7.')+ex('2.3','Changer de ton sans changer de degré','Transférer les repères.','Gammes de Do et Mi♭.','Donnez II, V et I en Do majeur, puis en Mi♭ majeur. Chantez les fondamentales dans une octave confortable au ténor.','Deux lignes de trois notes écrites.','Les degrés sont conservés et les notes changent.',('Commencez par écrire chaque gamme.','En Do, II est Ré.'),'Do : Ré–Sol–Do. Mi♭ : Fa–Si♭–Mi♭. Le même mouvement de degrés peut servir dans différentes tonalités.')),sec('revision','Fiche de révision',ready('Reconstruire une gamme majeure et retrouver I, II, III, V et VII sans hésitation.')+'<p><b>Erreurs fréquentes.</b> Compter la note de départ comme un demi-ton ; confondre un degré et un nombre de demi-tons ; ignorer l’orthographe de l’intervalle.</p><p><b>Résumé final.</b> Les intervalles décrivent les écarts. Les degrés décrivent les places dans une gamme. Ces deux outils permettent ensuite de construire des accords.</p>')]
    page('bases',bases)
    # 03 — Gammes : connaître la matière avant les accords.
    gamme_sections=[sec('objectif','Objectif & résumé général','<p>Construire quatre gammes et comprendre ce qui change dans le langage mineur. Les notes sont écrites pour le ténor. Commencez en Do pour comparer, puis travaillez en Mi♭ majeur et Do mineur pour préparer « Body and Soul ».</p>')]
    labels={'major':'Majeure','naturalMinor':'Mineure naturelle','harmonicMinor':'Mineure harmonique','melodicMinor':'Mineure mélodique jazz'}
    gamme_sections += [sec('comparer','Quatre gammes, note par note',table(['Gamme de Do écrite','Notes écrites','Ce qui change'],[[labels[k],notes_text(scale('C',k)),text] for k,text in [('major','Référence majeure : Mi, La, Si.'),('naturalMinor','Tierce, sixte et septième abaissées : Mi♭, La♭, Si♭.'),('harmonicMinor','La septième est relevée : Si naturel mène à Do.'),('melodicMinor','Sixte et septième relevées : La naturel et Si naturel.')]])+'<p>Une mineure naturelle est la gamme de base du mode mineur. La forme harmonique élève le degré 7 pour créer une sensible : une note située un demi-ton sous la tonique. La forme mélodique jazz relève également le degré 6 et s’emploie généralement de la même façon en montant et en descendant. Ce dernier usage diffère de la convention mélodique classique descendante.</p>'),sec('formules','Lire les formules d’intervalles','<p>Chaque nombre indique les demi-tons entre deux notes consécutives, jusqu’au retour à l’octave. Les écarts totalisent toujours 12.</p>'+table(['Gamme','Écarts successifs en demi-tons'],[['Majeure','2 · 2 · 1 · 2 · 2 · 2 · 1'],['Mineure naturelle','2 · 1 · 2 · 2 · 1 · 2 · 2'],['Mineure harmonique','2 · 1 · 2 · 2 · 1 · 3 · 1'],['Mineure mélodique jazz','2 · 1 · 2 · 2 · 2 · 2 · 1']])+'<p>Exemple : Do–Ré vaut 2 ; Ré–Mi♭ vaut 1 ; La♭–Si vaut 3 dans Do mineur harmonique. Ce grand intervalle ne doit pas être transformé en deux tons égaux.</p>'),sec('relatives','Majeur et mineur relatifs','<p>Mi♭ majeur et Do mineur naturel partagent trois bémols. Pourtant, leurs centres de repos sont différents : Mi♭ pour l’un, Do pour l’autre. Une armure commune ne signifie donc pas une tonique commune.</p>'+table(['Repère écrit ténor','Notes','Correspondance concert'],[['Mi♭ majeur',notes_text(scale('Eb')),'Ré♭ majeur'],['Do mineur naturel',notes_text(scale('C','naturalMinor')),'Si♭ mineur naturel'],['Do mineur harmonique',notes_text(scale('C','harmonicMinor')),'Si♭ mineur harmonique']]))]
    opts=''.join(f'<option value="{k}"'+(' selected' if k=='Eb' else '')+f'>{french(k)} ({pretty(k)})</option>' for k in KEYS)
    gamme_sections += [sec('atelier','Explorer une gamme écrite pour ténor',f'<div class="tool"><div class="controls"><label for="scale-key">Tonique écrite <select id="scale-key">{opts}</select></label><label for="scale-type">Gamme <select id="scale-type">'+''.join(f'<option value="{k}">{v}</option>' for k,v in labels.items())+'</select></label></div><h3 id="scale-name"></h3><div class="notes" id="scale-notes"></div><p class="mini" id="scale-concert"></p><div class="actions"><button class="btn primary" id="scale-play">Écouter pour ténor</button><button class="btn" id="scale-stop">Arrêter</button></div><p class="player-status" id="scale-status" aria-live="polite">Notes écrites affichées ; audio une neuvième majeure plus bas.</p></div>'),sec('usage','Une gamme n’est pas une phrase','<p>Montez la gamme, descendez-la, puis jouez trois notes et deux temps de silence. Chantez la tonique avant chaque essai. La gamme fournit une matière ; le rythme et les points de repos produisent la phrase.</p><p>Pour le moment, n’attribuez pas une gamme différente à chaque symbole. Le prochain chapitre construit d’abord les notes des accords ; les cadences expliqueront ensuite comment elles se relient.</p>'),sec('exercices','Trois étapes de travail',ex('3.1','La seule note qui change','Comparer naturel et harmonique.','Do mineur naturel.','Écrivez Do mineur naturel puis harmonique. Entourez la note différente et sa distance à Do aigu.','Deux gammes de sept notes.','Si♭ devient Si et se situe un demi-ton sous Do.',('La tierce reste Mi♭.','Seul le degré 7 est relevé.'),'Naturel : Do Ré Mi♭ Fa Sol La♭ Si♭. Harmonique : Do Ré Mi♭ Fa Sol La♭ Si. Si→Do est un demi-ton.')+ex('3.2','Construire dans un autre ton','Appliquer les écarts.','Formules de gammes.','Construisez Ré mineur naturel, harmonique puis mélodique jazz. Utilisez une fois chaque lettre.','Trois lignes de notes écrites.','Le Do devient Do♯ pour l’harmonique ; le Si♭ devient Si pour la mélodique.',('Ré mineur naturel contient Si♭.','La sensible de Ré est Do♯.'),'Naturel : Ré Mi Fa Sol La Si♭ Do. Harmonique : Ré Mi Fa Sol La Si♭ Do♯. Mélodique jazz : Ré Mi Fa Sol La Si Do♯.')+ex('3.3','Entendre la sensible','Relier calcul et oreille.','Do mineur harmonique.','Au ténor, alternez Si♭–Do puis Si–Do en noires. Ajoutez ensuite Mi♭–Ré–Do. Travaillez à 60, puis enregistrez deux répétitions de chaque.','Une courte comparaison enregistrée.','Les deux approches de Do restent distinctes et la pulsation ne change pas.',('Si♭→Do vaut un ton ; Si→Do vaut un demi-ton.','Les notes sont écrites pour le ténor : ne cherchez pas les sons réels sur sa partie.'),'La seconde approche crée la sensible Si→Do. Elle prépare le rôle de Si naturel dans G7, expliqué au chapitre de la cadence mineure.')),sec('revision','Fiche de révision',ready('Donner les notes de Mi♭ majeur et des trois formes de Do mineur, puis expliquer la sensible.')+'<p><b>Erreurs fréquentes.</b> Confondre relative et parallèle ; oublier de conserver Mi♭ dans Do mineur harmonique ; imposer les conventions classiques descendantes à la mineure mélodique jazz.</p><p><b>Résumé final.</b> Le mineur dispose de plusieurs formes. La sensible explique la tension vers la tonique ; la qualité de l’accord guidera le choix des notes.</p>')]
    page('gammes',gamme_sections)
    # 04 — Accords : chaque qualité est jouée comme un arpège au ténor.
    accord_sections=[sec('objectif','Objectif & résumé général','<p>Lire maj7, m7, 7, m7♭5 et °7 ; nommer leurs notes ; les jouer successivement au ténor. Un saxophone produit une ligne de notes : l’arpège fait entendre l’accord une note après l’autre.</p>'),old['bases'][3],sec('septièmes','La tierce et la septième précisent la famille','<p>Depuis Do, une tierce mineure est Mi♭ et une tierce majeure est Mi. La septième mineure est Si♭ ; la septième majeure est Si. Ces deux choix sont indépendants : Cm(maj7) possède une tierce mineure et une septième majeure.</p>'+chords_table([chord('C',q) for q in ['maj7','7','m7','m7b5','dim7','mMaj7','m6']])+call('La sixte n’est pas une septième','Cm6 contient Do–Mi♭–Sol–La. Sa quatrième note est une sixte, pas une septième. Dans la colonne de repérage ci-dessus, La est donc à lire comme sixte pour cet accord.')),
    sec('diatonique','Les accords de Mi♭ majeur écrit',chords_table([chord(r,q) for r,q in zip(scale('Eb'),['maj7','m7','m7','maj7','7','m7','m7b5'])])+'<p>Chaque accord prend une note sur deux dans la gamme. Les qualités obtenues sont Imaj7, IIm7, IIIm7, IVmaj7, V7, VIm7, VIIm7♭5. Ainsi, B♭7 contient La♭ ; A♭maj7 contient Sol. Remplacer A♭maj7 par A♭7 introduit Sol♭ et sort de l’harmonisation diatonique.</p>'),sec('arpeges','Du symbole à l’instrument','<p>Sur Fm7, jouez Fa–La♭–Do–Mi♭ en quatre noires. Reprenez en descendant Mi♭–Do–La♭–Fa. Alternez ensuite fondamentale–tierce–quinte–septième et tierce–quinte–septième–fondamentale à l’octave.</p><p>Travaillez dans une octave confortable et vérifiez les altérations avant de monter le tempo. Il n’est pas nécessaire de produire plusieurs notes simultanées au saxophone pour étudier l’harmonie.</p>'),sec('exercices','Reconnaître, construire, arpéger',ex('4.1','Un symbole, une note différente','Lire la septième.','Tierces et septièmes.','Écrivez Cmaj7 et C7, puis Fm7 et F7. Entourez la note qui change dans chaque paire.','Quatre accords écrits.','Si devient Si♭ dans la première paire ; La♭ devient La dans la seconde.',('maj7 change la septième ; m change la tierce.','Les fondamentales et quintes restent identiques.'),'Cmaj7 : Do Mi Sol Si ; C7 : Do Mi Sol Si♭. Fm7 : Fa La♭ Do Mi♭ ; F7 : Fa La Do Mi♭.')+ex('4.2','Reconnaître le demi-diminué','Distinguer deux familles voisines.','Accords à quatre sons.','Construisez Dm7♭5 et D°7. Donnez leurs notes et la différence de septième.','Deux accords et une explication.','Do appartient au demi-diminué ; Do♭ au diminué 7.',('Dm7♭5 contient une septième mineure.','D°7 contient une septième diminuée.'),'Dm7♭5 : Ré Fa La♭ Do. D°7 : Ré Fa La♭ Do♭. Do♭ est la septième diminuée de Ré ; au clavier il sonne comme Si.')+ex('4.3','Entendre les accords de la gamme','Relier un degré à son arpège.','Harmonisation de Mi♭ majeur.','Au ténor, jouez Fm7, B♭7 et E♭maj7 en quatre noires chacun. Une mesure par accord à 50–60. Dites les notes avant de les jouer.','Trois mesures enregistrées deux fois.','Les notes correspondent au tableau et les changements arrivent au premier temps.',('Lisez chaque accord indépendamment avant de l’enchaîner.','Fa La♭ Do Mi♭ ; Si♭ Ré Fa La♭ ; Mi♭ Sol Si♭ Ré.'),'Les trois accords sont correctement arpéggés si chaque mesure comporte fondamentale, tierce, quinte et septième. Le prochain chapitre explique leur lien fonctionnel.')),sec('revision','Fiche de révision',ready('Lire les cinq principales familles et jouer leurs quatre notes sans confondre 7 et maj7.')+'<p><b>Erreurs fréquentes.</b> Lire m7♭5 comme °7 ; prendre une sixte pour une septième ; nommer une fonction avant d’avoir vérifié les notes.</p><p><b>Résumé final.</b> La fondamentale nomme l’accord. Tierce, quinte et septième précisent sa qualité. L’arpège transforme ce vocabulaire en geste instrumental.</p>')]
    page('accords',accord_sections)
    # 05 — Cadence majeure : fonction et notes dans les douze tonalités.
    def all_cadence_rows(mode):
        return [[french(k), ' → '.join(c['symbol'] for c in cadence(k,mode)), '<br>'.join(c['symbol']+' : '+notes_text(c['notes']) for c in cadence(k,mode))] for k in KEYS]
    major=[sec('objectif','Objectif & résumé général','<p>Comprendre un II–V–I en commençant par Fm7 → B♭7 → E♭maj7, en Mi♭ majeur écrit pour ténor. La préparation, la tension et l’arrivée se vérifient avec les notes de la gamme.</p>'),sec('construire','Construire II, V et I dans une seule gamme',cadence_table('Eb','major')+'<p>Mi♭ majeur contient Mi♭–Fa–Sol–La♭–Si♭–Do–Ré. Au deuxième degré, empiler Fa–La♭–Do–Mi♭ donne Fm7. Au cinquième, Si♭–Ré–Fa–La♭ donne B♭7. Au premier, Mi♭–Sol–Si♭–Ré donne E♭maj7. Les trois accords appartiennent à la même gamme.</p><div class="formula">II m7 → V 7 → I maj7<br>Fa → Si♭ → Mi♭ : deux quartes ascendantes</div>'),sec('resoudre','Pourquoi la dominante appelle la tonique','<p>B♭7 contient le triton Ré–La♭ : six demi-tons. Ré peut monter à Mi♭, tandis que La♭ descend à Sol. Ces demi-tons font entendre l’arrivée sur la fondamentale et la tierce de E♭maj7.</p>'+call('Deux lignes possibles','Mi♭ → Ré → Ré : septième du II, tierce du V, septième du I. La♭ → La♭ → Sol : tierce du II, septième du V, tierce du I. On peut aussi faire résoudre Ré vers Mi♭ pour arriver sur la fondamentale.')+'<p>Le chiffre romain est une fonction ; le suffixe décrit une qualité. B♭7 est V7 en Mi♭, mais peut jouer un autre rôle dans un autre contexte.</p>'),sec('durees','Le rythme harmonique','<p>Le rythme harmonique décrit la vitesse des changements d’accord. Une même cadence peut occuper trois mesures, ou deux mesures avec II et V partageant la première.</p>'+table(['Grille écrite pour ténor','Durées en 4/4'],[['| Fm7 | B♭7 | E♭maj7 |','4 temps + 4 temps + 4 temps'],['| Fm7 B♭7 | E♭maj7 |','2 temps + 2 temps, puis 4 temps']])+'<p>Les fonctions et les notes ne changent pas. La phrase doit en revanche atteindre le bon accord au bon moment.</p>'),sec('atelier','Explorer la cadence majeure',explorer('major')),sec('douze-tons','Les accords dans les douze tons écrits',table(['Tonique écrite ténor','II–V–I','Notes de chaque accord'],all_cadence_rows('major'))+'<p>Commencez par Do, Fa, Si♭, Mi♭, puis Ré et Sol. Les tonalités restantes constituent une extension progressive, pas un exercice à terminer en une seule séance.</p>'),sec('exercices','Trois niveaux de maîtrise',ex('5.1','Retrouver la gamme commune','Justifier un II–V–I.','Harmonisation majeure.','Analysez Dm7 → G7 → Cmaj7. Écrivez la gamme commune puis les notes des trois accords.','Un tableau II, V, I en Do majeur écrit.','Toutes les notes appartiennent à Do majeur et le V contient Si–Fa.',('La destination est Do majeur.','II = Ré et V = Sol.'),'Dm7 : Ré Fa La Do ; G7 : Sol Si Ré Fa ; Cmaj7 : Do Mi Sol Si. La gamme de Do majeur confirme les trois qualités.')+ex('5.2','Deux accords dans une mesure','Respecter la vitesse des changements.','Arpèges et demi-mesures.','Sur | Fm7 B♭7 | E♭maj7 |, jouez La♭ deux temps, La♭ deux temps, puis Sol quatre temps. Répétez quatre fois à 60.','Huit mesures enregistrées.','La note Sol arrive au premier temps de chaque mesure paire.',('La♭ est commun à Fm7 et B♭7.','Le changement d’accord à B♭7 ne demande pas forcément un changement de hauteur.'),'La♭ est la tierce du II puis la septième du V. Sol est la tierce du I. La tenue commune permet d’entendre que la fonction change même si une note reste fixe.')+ex('5.3','Transposer une résolution','Conserver les degrés et les qualités.','Gamme de Ré majeur.','Écrivez le II–V–I en Ré majeur, puis jouez une ligne de tierces et septièmes : Sol → Sol → Fa♯.','Accords, notes et une phrase enregistrée.','Les accords sont Em7 A7 Dmaj7 et Fa♯ est la tierce d’arrivée.',('Ré majeur contient Fa♯ et Do♯.','La septième de A7 est Sol.'),'Em7 : Mi Sol Si Ré ; A7 : La Do♯ Mi Sol ; Dmaj7 : Ré Fa♯ La Do♯. La ligne suit tierce du II, septième du V, tierce du I.')),sec('revision','Fiche de révision',ready('Reconnaître, construire et jouer un II–V–I majeur dans trois tons, avec une justification par les notes.')+'<p><b>Erreurs fréquentes.</b> Appeler II–V–I n’importe quelle suite de trois accords ; oublier le rythme harmonique ; remplacer la septième mineure du V par une septième majeure.</p><p><b>Résumé final.</b> Le II prépare, le V crée une tension et le I établit un repos. Les tierces et septièmes rendent ce mouvement audible avec peu de notes.</p>')]
    page('ii-v-i-majeur',major)
    # 06 — Mineur : ne pas réduire toute la cadence à une seule gamme.
    minor=[sec('objectif','Objectif & résumé général','<p>Construire Dm7♭5 → G7 → Cm7 en Do mineur écrit pour ténor. Comprendre pourquoi le deuxième degré est demi-diminué et pourquoi la dominante contient Si naturel.</p><p>Correspondance de cet exemple : Cm7♭5 → F7 → B♭m7 en concert. Le cours et l’instrument continuent à lire Ré–Sol–Do.</p>'),sec('construire','Construire le II–V–I mineur',cadence_table('C','minor')+'<p>Dans Do mineur naturel, le deuxième degré donne Ré–Fa–La♭–Do : Dm7♭5. Pour créer une dominante forte, la septième de la gamme est relevée : Si♭ devient Si naturel. Sol–Si–Ré–Fa forme alors G7.</p><div class="formula">ii m7♭5 → V 7 → i mineur<br>Ré–Fa–La♭–Do → Sol–Si–Ré–Fa → Do–Mi♭–Sol–Si♭</div>'+call('Une cadence mineure combine des ressources','Do mineur harmonique explique Si naturel dans G7, mais Cm7 contient Si♭. Il serait incorrect d’affirmer que les trois accords proviennent intégralement d’une seule gamme harmonique inchangée. Les notes de l’accord courant restent la première référence.')),
    sec('tonique','Cm7, Cm(maj7) ou Cm6 ?',chords_table([chord('C',q) for q in ['m7','mMaj7','m6']])+'<p>Cm7 conserve Si♭, sa septième mineure. Cm(maj7) emploie Si naturel, sa septième majeure. Cm6 emploie La, sa sixte majeure. Le centre reste Do mineur, mais la couleur change. Respectez le symbole de la grille et la mélodie ; ces accords ne sont pas des remplacements automatiques.</p>'),sec('sensible','Les résolutions à entendre','<p>Dans G7, Si se trouve un demi-ton sous Do et Fa un ton au-dessus de Mi♭. Deux conduites utiles sont donc Si → Do et Fa → Mi♭. En partant du II : Do → Si → Si♭ suit septième de Dm7♭5, tierce de G7, septième de Cm7.</p><p>Une autre ligne conserve Fa sur le II et le V, puis descend vers Mi♭ sur le i. Avec Cm(maj7) à l’arrivée, la première ligne devient Do → Si → Si.</p>'),sec('extensions','Première extension : la neuvième mineure','<p>G7♭9 ajoute La♭ à Sol–Si–Ré–Fa. La♭ est situé un demi-ton au-dessus de Sol, donc une neuvième mineure quand on l’entend au-dessus de l’octave. Dans le passage Dm7♭5 → G7♭9, La♭ appartient déjà au premier accord ; il devient une tension sur le second.</p>'+table(['Accord écrit','Notes','Fonction dans Do mineur'],[['G7♭9','Sol · Si · Ré · Fa · La♭','V7 enrichi : la tierce reste Si naturel.']])+'<p>Travaillez d’abord G7 à quatre sons, puis ajoutez La♭ comme note de passage. Les dominantes altérées plus complexes viennent après la maîtrise de ces résolutions.</p>'),sec('atelier','Explorer la cadence mineure',explorer('minor')),sec('douze-tons','Les accords dans les douze tons écrits',table(['Tonique mineure écrite','ii–V–i avec i7','Notes de chaque accord'],all_cadence_rows('minor'))+'<p>Une double altération garde le nom du degré : par exemple, Si♭♭ est la quinte diminuée de Mi♭. Dans les tonalités théoriques plus chargées, choisir une écriture enharmonique peut simplifier la lecture. Commencez par Do, Ré, Sol et La mineurs.</p>'),sec('exercices','Trois étapes vers le mineur',ex('6.1','Le deuxième degré','Construire le demi-diminué.','Do mineur naturel.','Écrivez les notes de Dm7♭5 et comparez-les à Dm7. Entourez la différence.','Deux accords de quatre notes.','La devient La♭ ; la tierce reste Fa.',('Démarrez sur Ré et empilez les tierces de Do mineur naturel.','m7♭5 conserve une septième mineure.'),'Dm7 : Ré Fa La Do. Dm7♭5 : Ré Fa La♭ Do. La quinte abaissée distingue les deux accords.')+ex('6.2','Faire entendre la sensible','Justifier la dominante mineure.','G7 et Do mineur.','Jouez Si → Do sur G7 → Cm7, puis Fa → Mi♭. Écrivez la fonction de chaque note. Deux temps par note, à 60.','Deux résolutions enregistrées et annotées.','Si reste naturel et Fa descend vers Mi♭.',('Si est la tierce de G7.','Do est la fondamentale de Cm7 ; Mi♭ sa tierce mineure.'),'Si→Do : tierce du V vers fondamentale du i, par demi-ton. Fa→Mi♭ : septième du V vers tierce du i, par ton.')+ex('6.3','Transférer en Ré mineur','Construire une cadence complète.','Ré mineur naturel et harmonique.','Écrivez ii–V–i en Ré mineur avec une arrivée Dm7. Donnez toutes les notes et indiquez celle qui vient de la forme harmonique.','Trois accords et une ligne de notes guides.','Em7♭5 A7 Dm7 ; Do♯ appartient à la dominante.',('Le V de Ré est La.','La sensible de Ré est Do♯, mais Dm7 contient Do naturel.'),'Em7♭5 : Mi Sol Si♭ Ré. A7 : La Do♯ Mi Sol. Dm7 : Ré Fa La Do. Ligne possible : Sol→Sol→Fa. Do♯ explique la tension du V ; Do naturel définit la septième de Dm7.')),sec('revision','Fiche de révision',ready('Distinguer cadence majeure et mineure, puis expliquer les notes de la dominante et de l’accord d’arrivée.')+'<p><b>Erreurs fréquentes.</b> Jouer Gm7 à la place de G7 dans cette cadence ; oublier La♭ dans Dm7♭5 ; imposer Si naturel sur un accord Cm7 parce qu’on vient de jouer la gamme harmonique.</p><p><b>Résumé final.</b> Le ii est demi-diminué. Le V possède une tierce majeure qui crée la sensible. Le i conserve la couleur indiquée par son symbole.</p>')]
    page('ii-v-i-mineur',minor)
    # 07 — Construire une ligne horizontale.
    guides=[sec('objectif','Objectif & résumé général','<p>Relier les accords en faisant bouger peu de notes. Après les arpèges verticaux, la conduite des voix suit une note dans le temps. Les exemples sont écrits pour ténor.</p>'),sec('majeur','Deux lignes sur la cadence majeure',table(['Accord','Fm7','B♭7','E♭maj7'],[['Ligne 1','Mi♭ : septième','Ré : tierce','Ré : septième'],['Ligne 2','La♭ : tierce','La♭ : septième','Sol : tierce']])+'<p>Jouez d’abord chaque ligne séparément. Entendez les notes communes et les demi-tons. Une note tenue peut changer de rôle quand l’accord change : La♭ passe de tierce de Fm7 à septième de B♭7.</p>'),sec('mineur','Deux lignes sur la cadence mineure',table(['Accord','Dm7♭5','G7','Cm7'],[['Ligne 1','Do : septième','Si : tierce','Si♭ : septième'],['Ligne 2','Fa : tierce','Fa : septième','Mi♭ : tierce']])+'<p>La première ligne descend chromatiquement Do–Si–Si♭. Elle respecte les trois accords sans réduire le passage à une seule gamme mineure. Avec Cm(maj7), l’arrivée serait Si naturel.</p>'),sec('phrase','Ajouter le rythme et l’espace','<p>Choisissez une note cible par accord, puis un rythme de quatre temps. Exemple sur | Fm7 B♭7 | E♭maj7 | : La♭ en blanche, La♭ en blanche ; Sol en blanche suivi de deux temps de silence.</p><p>Une note cible est une destination prévue. Elle n’oblige pas à attaquer chaque premier temps : commencez par ce repère, puis explorez des anticipations lorsque la pulsation est stable.</p>'),sec('exercices','Des notes aux phrases',ex('7.1','Nommer le rôle d’une note commune','Entendre une fonction qui change.','Tierces et septièmes.','Écrivez le rôle de La♭ dans Fm7 et B♭7. Jouez quatre temps sur chaque accord en gardant cette seule note.','Deux mesures et leur annotation.','La♭ est tierce puis septième.',('Lisez les notes de chaque accord.','La fondamentale change de Fa à Si♭.'),'Fm7 : La♭ est la tierce mineure. B♭7 : La♭ est la septième mineure. La hauteur reste fixe tandis que la fonction change.')+ex('7.2','Une ligne chromatique en mineur','Relier trois accords sans sauts.','Cadence mineure.','Jouez Do–Si–Si♭ sur | Dm7♭5 | G7 | Cm7 |, une ronde par accord. Annoncez le rôle de chaque note.','Trois mesures enregistrées.','Les deux mouvements sont des demi-tons descendants.',('La première note est une septième.','Le milieu doit contenir Si naturel.'),'Septième du ii, tierce du V, septième du i. Les trois notes appartiennent chacune à leur accord.')+ex('7.3','Inventer avec une contrainte','Créer une phrase lisible harmoniquement.','Cadences et notes guides.','Sur | Fm7 B♭7 | E♭maj7 |, choisissez La♭ puis Sol comme cibles. Ajoutez au plus deux notes d’accord et au moins deux temps de silence sur les deux mesures.','Une phrase de deux mesures écrite et enregistrée.','Les changements d’accord et les quatre temps restent respectés.',('Comptez d’abord les durées sans jouer.','Un exemple peut tenir dans six attaques ou moins.'),'Exemple : Fa et La♭ en noires sur les temps 1 et 2 ; La♭ en blanche sur B♭7 aux temps 3–4. Mesure suivante : Sol en blanche, deux temps de silence. Toutes les notes sont écrites pour ténor.')),sec('revision','Fiche de révision',ready('Jouer deux lignes guides en majeur et deux en mineur, puis construire une phrase avec silence.')+'<p><b>Erreurs fréquentes.</b> Ajouter des notes avant de savoir où arriver ; croire qu’une note commune conserve la même fonction ; perdre la mesure pendant le silence.</p><p><b>Résumé final.</b> Une ligne simple peut dire beaucoup d’harmonie. La qualité du mouvement et le placement comptent autant que le nombre de notes.</p>')]
    page('notes-guides',guides)
    # 08 — Forme, rythme harmonique et exemples de standards.
    study=study_grid()
    (out/'assets/etude-aaba.svg').write_text(form_diagram(study))
    structures=[sec('objectif','Objectif & résumé général','<p>Lire une grille comme une histoire : des mesures forment des phrases, les phrases construisent des sections, et les sections organisent le morceau. Repérez la forme avant de chercher toutes les substitutions.</p>'),sec('methode','Une méthode en cinq lectures','<ol><li><b>Convention.</b> Lire la tonalité et vérifier que la grille est destinée au ténor Si♭.</li><li><b>Temps.</b> Compter les mesures et noter la durée de chaque accord.</li><li><b>Sections.</b> Repérer les blocs qui reviennent : A, B, retours et fins différentes.</li><li><b>Destinations.</b> Entourer les accords de repos, puis les dominantes qui les précèdent.</li><li><b>Cadences.</b> Vérifier les II–V–I majeurs et ii–V–i mineurs avec leurs notes.</li></ol><p>Une anacrouse, une introduction et une coda se repèrent séparément. Ne les ajoutez pas arbitrairement aux mesures du refrain.</p>'),sec('formes','AABA, ABAC et blues',table(['Forme','Plan de travail','Question à poser'],[['AABA de 32 mesures','A₁ : 1–8 · A₂ : 9–16 · B : 17–24 · A₃ : 25–32','Les fins des trois A sont-elles identiques ?'],['ABAC de 32 mesures','Quatre sections de huit mesures dans ce modèle','Comment le second A prépare-t-il une autre conclusion ?'],['Blues de 12 mesures','Trois groupes de quatre mesures','Où passent I7, IV7 et V7 ?']])+'<p>Les lettres décrivent des ressemblances de matériau, pas une règle universelle de tonalité. Le pont B peut moduler, mais le nom B n’impose aucune modulation.</p>'),sec('autumn','Autumn Leaves : majeur et mineur dans la même phrase','<p>Voici une réduction courante des huit premières mesures, en <b>La mineur écrit pour ténor</b>, correspondant à Sol mineur concert. Elle permet de comparer une cadence en Do majeur et une cadence vers sa relative mineure.</p>'+table(['Mesure','Accord écrit ténor','Fonction locale'],[['1','Dm7','II de Do majeur'],['2','G7','V de Do majeur'],['3','Cmaj7','I de Do majeur'],['4','Fmaj7','IV de Do majeur : liaison entre les deux zones'],['5','Bm7♭5','iiø de La mineur'],['6','E7','V de La mineur : Sol♯ sensible'],['7','Am7','i de La mineur'],['8','Am7','Prolongement de la tonique']])+chords_table([chord(r,q) for r,q in [('D','m7'),('G','7'),('C','maj7'),('F','maj7'),('B','m7b5'),('E','7'),('A','m7')]])+'<p>Le repos général peut rester La mineur même si une cadence locale éclaire Do majeur. L’arrivée du Sol♯ dans E7 rend le retour à La particulièrement clair. La tonalité et les enrichissements varient selon les éditions.</p><p class="source-note">Le rapprochement entre majeur et relative mineure est présenté dans l’<a href="https://www.jazzguitar.be/blog/autumn-leaves-melody-and-solo">étude d’Autumn Leaves de Dirk Laukens</a> ; l’extrait ci-dessus est transposé et réduit pour le ténor.</p>'),sec('misty','Misty : une cadence vers le IV','<p>En Fa majeur écrit pour ténor, correspondant à Mi♭ concert, le début usuel fait entendre | Fmaj7 | Cm7 F7 | B♭maj7 |. L’accord d’arrivée est le IV de Fa, mais devient un I local pendant la cadence.</p>'+chords_table([chord(r,q) for r,q in [('F','maj7'),('C','m7'),('F','7'),('Bb','maj7')]])+'<p>Cm7 → F7 → B♭maj7 est II–V–I en Si♭ majeur. F7 contient Mi♭, alors que Fmaj7 contient Mi naturel. Ce seul changement prépare une nouvelle destination. On parle ici de <b>tonicisation</b> du IV : un éclairage local, sans conclure automatiquement à une modulation durable.</p><p class="source-note">Organisation harmonique : <a href="https://www.jazzguitarcomprehensive.com/rep/misty">JGC, Misty</a>.</p>'),sec('etude','Une étude originale sur 32 mesures','<p>La grille suivante est une <b>composition pédagogique originale AABA</b>, écrite pour ténor en Mi♭ majeur. Elle fournit un terrain complet pour le projet du parcours ; elle ne constitue pas la grille de « Body and Soul ».</p>'+'<a href="assets/etude-aaba.svg"><img class="flow-svg" src="assets/etude-aaba.svg" alt="Carte de trente-deux mesures : A1, A2, B et A3, avec les accords écrits pour ténor."></a>'+original_grid(study)+'<p>A₁ termine sur C7 pour préparer Fm7 au retour de A₂. La mesure 16 termine sur E♭7, qui conduit au La♭ majeur du pont. Dans B, Gm7♭5 → C7 → Fm7 établit un ii–V–i en Fa mineur, puis B♭7 prépare le retour de A₃. La mesure 31 accélère les changements ; la mesure 32 conclut sur E♭maj7.</p>'),sec('exercices','Lire une grille, pas seulement des symboles',ex('8.1','Compter les quatre blocs','Repérer la forme AABA.','Mesures à quatre temps.','Dans l’étude originale, marquez les entrées de section puis comptez un refrain sans instrument à 60 à la noire.','Une carte de 32 cases.','Les entrées sont 1, 9, 17 et 25 ; le total est 128 temps.',('Chaque section contient huit mesures.','Une mesure compte quatre noires.'),'A₁ 1–8, A₂ 9–16, B 17–24, A₃ 25–32. 32 × 4 = 128 pulsations.')+ex('8.2','Comparer deux cadences voisines','Lire majeur et relative mineure.','Cadences majeures et mineures.','Dans l’extrait d’Autumn Leaves, nommez les deux tonalités locales et la note caractéristique de la seconde dominante.','Deux analyses de trois accords.','Do majeur, La mineur et Sol♯ dans E7 sont identifiés.',('Le dernier accord de chaque groupe suggère la destination.','E7 contient Mi Sol♯ Si Ré.'),'Dm7 G7 Cmaj7 : II–V–I en Do majeur. Bm7♭5 E7 Am7 : ii–V–i en La mineur. Sol♯ est la sensible de La.')+ex('8.3','Comprendre les fins différentes','Relier forme et harmonie.','L’étude originale AABA.','Comparez les mesures 8, 16 et 32. Donnez leurs accords et la destination attendue après chacune.','Trois flèches annotées.','C7 mène vers Fa mineur ; E♭7 vers La♭ majeur ; E♭maj7 conclut.',('La fin d’une section peut préparer la suivante.','La dernière mesure utilise maj7, pas 7.'),'Mesure 8 : C7→Fm7, dominante vers le II mineur de la tonalité principale. Mesure 16 : E♭7→A♭maj7. Mesure 32 : repos sur E♭maj7. Les trois A ne portent pas la même fin.')),sec('revision','Fiche de révision',ready('Dessiner la forme, compter les mesures et justifier au moins une cadence majeure et une mineure dans une grille.')+'<p><b>Erreurs fréquentes.</b> Confondre répétition de section et identité de sa fin ; ignorer les durées quand plusieurs accords partagent une mesure ; appeler modulation chaque dominante secondaire.</p><p><b>Résumé final.</b> Forme, rythme harmonique et fonctions se lisent ensemble. La cadence est un événement dans une phrase, pas seulement une liste de trois noms.</p>')]
    page('structure',structures)
    # 09 — Application à Body and Soul : convention désormais fixée pour le cours.
    body=[]
    for sid,title,text in old['body-and-soul']:
        if sid=='partition':
            text='<p>Le travail se fait en <b>Mi♭ majeur écrit pour saxophone ténor Si♭</b>, correspondant à Ré♭ majeur concert. Les symboles −7 se lisent m7. Les extraits étudiés sont donnés dans leur ordre ; les réductions pédagogiques sont explicitement signalées.</p>'+table(['Mesure de A','Accords écrits ténor'],[['1','Fm7 · C7♭9'],['2','Fm7 · B♭7'],['3','E♭maj7 · A♭7'],['4','Gm7 · F♯°7']])+ '<p>La lecture retenue pour le passage diminué de la mesure 4 est F♯°7. Ses notes Fa♯–La–Do–Mi♭ conduisent vers Fa–La♭–Do–Mi♭ de Fm7.</p><details><summary>Consulter la partition de référence</summary><div><a href="assets/partition-reference.png">Ouvrir la partition</a></div></details>'
            title='Tonalité et premiers accords'
        text=text.replace('notation en Mi♭','notation ténor en Mi♭').replace('Notation en Mi♭','Notation ténor en Mi♭').replace('Si la photo','Si la partition')
        body.append(sec(sid,title,text))
    reduced=[['1','Fm7 · C7♭9','2 + 2','Préparation ; dominante de Fa mineur'],['2','Fm7 · B♭7','2 + 2','II–V de Mi♭ majeur'],['3','E♭maj7 · A♭7','2 + 2','I majeur, puis couleur IV7'],['4','Gm7 · F♯°7','2 + 2','Accord de passage vers Fm7'],['5','Fm7','4','Prolongement du II'],['6','Dm7♭5 · G7','2 + 2','ii–V de Do mineur'],['7','Cm7 · Fm7 · B♭7','2 + 1 + 1','i de Do mineur, puis II–V de Mi♭'],['8','E♭6','4','Retour à la tonique']]
    insert=next(i for i,x in enumerate(body) if x[0]=='couleurs')
    body.insert(insert,sec('grille','Réduction de travail du A : huit mesures','<p>Cette réduction pédagogique conserve les principales destinations harmoniques. Elle simplifie les renversements et la fin du A pour travailler la résolution ; elle ne remplace pas toutes les variantes d’une édition ou d’un arrangement. Les durées proposées totalisent quatre temps par mesure.</p>'+table(['Mesure','Accords écrits pour ténor','Temps','Lecture'],reduced)+'<p>En huit mesures, deux destinations apparaissent : Mi♭ majeur aux mesures 2–3 et Do mineur aux mesures 6–7. Il n’est donc pas suffisant de choisir une seule gamme majeure pour tout le A.</p>'+chords_table([chord(r,q) for r,q in [('F','m7'),('Bb','7'),('Eb','maj7'),('Ab','7'),('G','m7'),('F#','dim7'),('D','m7b5'),('G','7'),('C','m7'),('Eb','6')]])))
    page('body-and-soul',body)
    # 10 — Rythme : la difficulté se construit par étapes observables.
    rhythm=[]
    for sid,title,text in old['rythme']:
        if sid=='objectif':
            text='<p>Stabiliser quatre pulsations, placer six noires de triolet, puis transformer le motif avec des liaisons et des silences. Les huit niveaux vont d’une seule note régulière à une phrase de quatre mesures qui suit les accords.</p>'+call('Une progression à valider','Commencez entre 40 et 60 à la noire. Passez au niveau suivant après quatre mesures régulières répétées trois fois. Augmentez le tempo par petits pas, sans sacrifier le comptage ni la qualité du souffle.')
        if sid=='ecouter':
            text=text.replace('<option value="triplets">','<option value="quarters">Niveau 1 · quatre noires</option><option value="triplets">')
            text=text.replace('<option value="quarters">Repère · quatre noires</option>','<option value="rests">Niveau 6 · silences dans les triolets</option>')
        if sid=='exercices':
            text=ex('10.1','La pulsation avant les subdivisions','Garder quatre temps égaux.','Noire et silence.','À 60, jouez une seule note confortable en quatre noires par mesure. Répétez quatre mesures, puis gardez les temps 2 et 4 au métronome.','Deux séries de quatre mesures.','16 attaques par série et aucune accélération entre 2 et 4.',('Comptez les quatre temps même lorsque deux clics disparaissent.','Le clic reste réglé à 60 à la noire : seuls les temps 2 et 4 sont audibles.'),'Les attaques restent à 0, 1, 2 et 3 temps. Le clic sur 2 et 4 ne change ni le tempo ni la durée de la mesure.')+ex('10.2','Six positions sur quatre temps','Placer les triolets de noires réguliers.','Pulsation stable.','Subdivisez chaque temps en trois, puis attaquez une petite unité sur deux. Jouez quatre mesures sur une seule note, avec le motif 1 du lecteur.','24 attaques sur quatre mesures.','Les débuts des deux groupes coïncident avec les temps 1 et 3.',('Comptez douze petites unités par mesure.','Attaquez les unités 0, 2, 4, 6, 8 et 10.'),'Les départs sont 0 ; ⅔ ; 1⅓ ; 2 ; 2⅔ ; 3⅓ temps. La mesure suivante commence à 4.')+ex('10.3','La liaison entre deux groupes','Prolonger sans réattaquer sur le temps 3.','Triolets réguliers.','Jouez le motif 2 : liez la troisième position du premier groupe à la première du second. Gardez le souffle sur la liaison.','Quatre mesures de cinq attaques.','Le temps 3 reste compté et ne porte pas de nouvelle attaque.',('Une position liée n’est pas un silence.','Comptez 1–2–3 / (lié)–2–3.'),'Le son commencé à 1⅓ temps se prolonge jusqu’à 2⅔ temps. Les cinq attaques sont à 0, ⅔, 1⅓, 2⅔ et 3⅓.')+ex('10.4','Deux liaisons indépendantes','Conserver le comptage malgré deux attaques retirées.','Motif 2 maîtrisé.','Jouez le motif 3 : liez 1→2 dans le premier groupe, puis 3→1 entre les groupes. Répétez quatre fois sans changer la pulsation.','Quatre mesures avec quatre attaques chacune.','Les attaques tombent à 0, 1⅓, 2⅔ et 3⅓ temps.',('Il y a toujours six positions, mais seulement quatre attaques.','Les liaisons concernent les positions 1→2 et 3→4 de la série de six.'),'Les durées successives des sons sont 1⅓, 1⅓, ⅔ et ⅔ temps : total 4. Le souffle traverse les deux positions liées.')+ex('10.5','Déplacer les appuis','Comparer deux motifs de même densité.','Deux liaisons.','Alternez une mesure de Variation A et une mesure de Variation B, quatre fois. A lie 2→3 et 5→6 ; B lie 1→2 et 4→5.','Huit mesures, quatre attaques dans chacune.','Les deux motifs gardent quatre temps mais présentent des départs différents.',('A commence par deux attaques rapprochées.','B commence par une note prolongée.'),'A : départs 0, ⅔, 2 et 2⅔. B : 0, 1⅓, 2 et 3⅓. Même nombre d’attaques, autre placement.')+ex('10.6','Remplacer la prolongation par un silence','Distinguer liaison et absence de son.','Motif 3 et silences.','Sur la série de six positions, jouez 1, silence, 3 / silence, 2, 3. Chaque position vaut ⅔ de temps. Comparez ce motif au motif 3 lié.','Deux mesures liées puis deux mesures avec silences.','Les attaques ont les mêmes positions, mais le souffle s’arrête aux deuxième et quatrième positions.',('Un silence occupe une durée sans son.','Utilisez le mode « silences dans les triolets » du lecteur.'),'Attaques à 0, 1⅓, 2⅔ et 3⅓. Les silences occupent [⅔,1⅓] et [2,2⅔]. La version liée garde du son sur ces intervalles ; la version avec silences les libère.')+ex('10.7','Deux mesures, un seul fil','Garder les repères avec un clic réduit.','Liaisons et silences.','Sur une note, alternez une mesure du motif 2 et une mesure du motif à silences. Travaillez avec clic sur 2 et 4, puis avec une mesure de décompte seulement.','Huit mesures enregistrées en deux conditions.','Aucune dérive au retour de la première mesure ; les silences gardent leur durée.',('Comptez les huit temps de chaque paire avant de jouer.','Il n’y a pas de pause supplémentaire entre les deux mesures.'),'Chaque paire occupe huit temps : cinq attaques liées puis quatre attaques avec silences. Revenez au clic sur chaque temps si la jonction décale le premier temps.')+ex('10.8','Une phrase rythmique sur la cadence','Réunir pulsation, souffle et notes cibles.','II–V–I et niveaux précédents.','Sur | Fm7 | B♭7 | E♭maj7 | E♭maj7 |, jouez La♭ avec le motif 1, La♭ avec le motif 2, puis Sol avec le motif à silences. Terminez par Sol en blanche et deux temps de silence. Tout est écrit pour ténor.','Quatre mesures enregistrées, puis une seconde prise améliorée.','Les notes suivent les accords ; la dernière mesure respire ; les quatre premiers temps restent réguliers.',('La♭ est tierce du II puis septième du V.','Sol est la tierce de l’accord d’arrivée.'),'La densité est de 6, 5, 4 puis 1 attaque : 16 attaques au total. Les deux premières mesures gardent La♭, mais l’accord change ; l’arrivée Sol rend la résolution audible. Le silence final compte deux temps.')
        rhythm.append(sec(sid,title,text))
    rhythm.insert(next(i for i,x in enumerate(rhythm) if x[0]=='exercices'),sec('progression','Les huit niveaux',table(['Niveau','Difficulté ajoutée','Repère de réussite'],[['1','Quatre noires, puis clic sur 2 et 4','16 attaques sur quatre mesures'],['2','Six noires de triolet','Six attaques par mesure'],['3','Une liaison entre groupes','Cinq attaques, souffle continu sur le temps 3'],['4','Deux liaisons','Quatre attaques, quatre temps'],['5','Déplacement des liaisons','Même densité, autre placement'],['6','Silences de noires de triolet','Même comptage, souffle interrompu'],['7','Deux mesures et clic réduit','Huit temps conservés sans pause ajoutée'],['8','Notes cibles et cadence','Quatre mesures avec arrivée et respiration']])) )
    page('rythme',rhythm)
    # 11 — Conserver les couleurs blues, avec l'écrit ténor comme convention principale.
    blues=[]
    for sid,title,text in old['blues']:
        text=text.replace('Explorer les notes / sons réels','Explorer les notes / écrit ténor Si♭').replace('Tonique <select id="blues-key"','Tonique écrite <select id="blues-key"')
        text=text.replace('Toutes les notes de cet outil sont en sons réels, même si vous jouez du ténor.','Les noms affichés sont écrits pour ténor. L’audio produit les sons réels, une neuvième majeure plus bas.')
        text=text.replace('Le clavier présente une octave de Do à Do ;','Le clavier repère les notes écrites, sans représenter l’accompagnement concert. Il présente une octave de Do à Do ;')
        text=text.replace('Recommencez en Ré♭ concert :','Correspondance pour un instrument en sons réels, en Ré♭ concert :')
        blues.append(sec(sid,title,text))
    page('blues',blues)
    # 12 — La carte garde l'armure majeure et compare deux types de cadences.
    cycles=[]
    for sid,title,text in old['cycle']:
        text=text.replace('Les notes affichées sont des <b>sons réels ou des noms théoriques</b> ; aucune transposition instrumentale n’est automatique.','Les notes et les accords affichés sont <b>écrits pour ténor Si♭</b>. L’armure affichée correspond au majeur ; la cadence mineure de même tonique est présentée séparément.')
        text=text.replace('<div class="notes" id="circle-notes"></div>','<div class="notes" id="circle-notes"></div><div class="callout"><strong>Même tonique, cadence mineure</strong><p id="circle-minor-cadence"></p><div id="circle-minor-chords"></div><p class="mini">La mineure de même tonique a une autre armure. Le V7 emploie la sensible ; les notes de chaque accord sont précisées ci-dessus.</p></div>')
        text=text.replace('Les fondamentales Mi♭ → La♭ → Ré♭ de la cadence concert se suivent dans le sens des quartes ascendantes. En Mi♭ majeur : Fa → Si♭ → Mi♭.','Les fondamentales Fa → Si♭ → Mi♭ de la cadence écrite pour ténor se suivent dans le sens des quartes ascendantes. Leur correspondance concert est Mi♭ → La♭ → Ré♭.')
        cycles.append(sec(sid,title,text))
    cycles.insert(next(i for i,x in enumerate(cycles) if x[0]=='exercices'),sec('entrainement','Un cycle de travail majeur puis mineur','<p>Choisissez trois tons écrits voisins : Do, Fa, Si♭. Pour chaque ton, construisez d’abord le II–V–I majeur puis le ii–V–i mineur de même tonique. Ne changez pas les trois fondamentales : c’est la qualité du II et de l’accord d’arrivée qui se transforme.</p>'+table(['Tonique écrite','Majeur','Mineur'],[[french(k),' → '.join(c['symbol'] for c in cadence(k)),' → '.join(c['symbol'] for c in cadence(k,'minor'))] for k in ['C','F','Bb','Eb']])+'<p>À l’étape suivante, transposez une seule ligne guide dans ces quatre tons. La vitesse ne doit augmenter que lorsque les notes et les arrivées sont sûres.</p>'))
    page('cycle',cycles)
    # 13 — Un projet continu et des jalons correspondant à chaque étape du parcours.
    milestones=[('Établir les deux conventions','Inscrire Mi♭ écrit ténor / Ré♭ concert en tête du carnet.','Les fondamentales et les qualités sont transposées une fois.'),('Retrouver les degrés','Annoter I, II, V et VI dans Mi♭ majeur.','Mi♭, Fa, Si♭, Do sont correctement placés.'),('Construire les gammes','Ajouter Mi♭ majeur et les trois formes de Do mineur.','Le Si naturel de la forme harmonique est identifié.'),('Construire les accords','Écrire les notes des accords de l’étude originale.','m7, 7, maj7 et m7♭5 sont distincts.'),('Repérer le majeur','Entourer Fm7 B♭7 E♭maj7 dans A.','La gamme commune et les notes sont justifiées.'),('Repérer le mineur','Annoter Dm7♭5 G7 Cm7 dans A.','Si naturel dans G7, Si♭ dans Cm7.'),('Tracer les notes guides','Écrire une ligne par cadence, avec les rôles de notes.','Les notes appartiennent à leurs accords.'),('Cartographier la forme','Compléter les 32 mesures AABA et leurs durées.','Les fins des A et les entrées de section sont reconnues.'),('Comparer au standard','Analyser les arrivées majeures et mineures du A de Body and Soul.','La réduction d’étude et le standard restent distingués.'),('Ajouter le rythme','Choisir deux motifs liés et un motif à silences.','Quatre temps par mesure et pas de réattaque sur la liaison.'),('Ajouter une couleur blues','Écrire une approche ♭3→3 sur E♭maj7.','Sol♭ se résout vers Sol au bon endroit.'),('Transposer une cadence','Déplacer le II–V–I en Fa puis Si♭ écrits.','Qualités et fonctions conservées, notes vérifiées.'),('Enregistrer une interprétation','Jouer l’étude entière, puis améliorer une prise.','32 mesures, repères fiables, notes cibles et respirations.')]
    project='<p>Le fil rouge est un <b>carnet d’étude et une interprétation de la grille AABA originale</b>. Le carnet s’enrichit à chaque chapitre : notes, accords, cadences, forme, rythme puis phrases. « Body and Soul » fournit l’étude de standard à laquelle comparer ces repères.</p><h3>Contexte et objectif</h3><p>Un saxophoniste ténor prépare une interprétation avec un accompagnateur. Le problème à résoudre est de garder la forme tout en choisissant des notes qui décrivent l’harmonie. La grille complète est disponible au chapitre <a href="structure.html#etude">Structure</a>.</p><h3>Organisation du travail</h3><p>Une carte de 32 mesures, une liste d’accords avec leurs notes, des lignes guides, une page de rythmes et des enregistrements. Conserver ces mêmes documents pendant toute la progression.</p>'+table(['Chapitre','Notion et production','Validation observable'],[[str(i+1)+' · '+chapters[i][2],f'<b>{m[0]}</b><br>{m[1]}',m[2]] for i,m in enumerate(milestones)])+'<h3>Livrables</h3><ul><li>Une grille AABA annotée de 32 mesures, explicitement écrite pour ténor Si♭.</li><li>Une cadence majeure et une cadence mineure avec notes et fonctions.</li><li>Une ligne guide par section et trois motifs rythmiques expliqués.</li><li>Un enregistrement complet : au moins deux temps de silence par section et une arrivée audible sur les cadences principales.</li><li>Une auto-évaluation localisant deux réussites et une difficulté dans une mesure précise.</li></ul><h3>Critères et erreurs à observer</h3><p>Vérifier les notes à l’accord courant, le premier temps de chaque section, la durée des liaisons et la compatibilité avec l’accompagnement. Observer notamment la double transposition, la confusion entre Si et Si♭ dans Do mineur, et le décalage d’une mesure au retour de A.</p><h3>Extensions facultatives</h3><p>Transposer une section, enregistrer deux placements rythmiques différents d’une même phrase, puis appliquer la méthode à une grille complète de « Body and Soul ».</p>'
    # QCM : conserver les huit repères et ajouter deux distinctions centrales du nouveau parcours.
    questions=env['questions']+[
        ('Dans Dm7♭5 → G7 → Cm7, quelles septième/tierce distinguent le V et le i ?',['Si♭ dans G7, Si dans Cm7','Si dans G7, Si♭ dans Cm7','Si♭ dans les deux','Si dans les deux'],'B','G7 contient Si naturel comme tierce ; Cm7 contient Si♭ comme septième mineure. La cadence emploie plusieurs ressources du mineur.'),
        ('Dans Misty en Fa majeur écrit, Cm7 → F7 → B♭maj7 forme…',['Un II–V–I en Si♭ majeur, IV local de Fa','Un II–V–I en Fa majeur','Un ii–V–i en Do mineur','Trois accords sans destination identifiable'],'A','Si♭ est le IV de Fa, mais la cadence l’éclaire comme tonique locale. F7 contient Mi♭ et conduit vers B♭maj7.')]
    quiz='<form class="quiz" id="quiz" onsubmit="return false">'
    for i,(q,answers,right,explanation) in enumerate(questions):
        from html import escape
        quiz+=f'<fieldset data-answer="{right}" data-explanation="{escape(explanation,quote=True)}"><legend>{i+1}. {q}</legend>'+''.join(f'<label><input type="radio" name="q{i}" value="{chr(65+j)}"> <span>{chr(65+j)}. {a}</span></label>' for j,a in enumerate(answers))+'<p class="feedback" hidden></p></fieldset>'
    quiz+='<button class="btn primary" id="quiz-submit" type="button">Vérifier mes réponses</button><p class="quiz-result" id="quiz-result" role="status" hidden></p></form><details><summary>Corrigé du QCM en lecture libre</summary><div><ol>'+''.join(f'<li><b>{right}.</b> {explanation}</li>' for _,_,right,explanation in questions)+'</ol></div></details>'
    practice=[]
    for sid,title,text in old['pratique']:
        if sid=='objectif':text='<p>Réunir les acquis du parcours dans une interprétation au saxophone ténor en Si♭ : lire les accords écrits, reconnaître les cadences, suivre les sections et construire une phrase qui respire.</p>'
        if sid=='projet':text=project
        if sid=='qcm':text=quiz
        if sid=='fiche':
            text='<div class="summary-grid"><div><h3>Les accords et leurs fonctions</h3><p>Écrit ténor : Fm7 → B♭7 → E♭maj7.<br>Mineur : Dm7♭5 → G7 → Cm7.<br>Tierces et septièmes : premières notes guides.<br>La sensible Si mène à Do dans le mineur.<br>Le i peut être m7, m(maj7) ou m6 selon la grille.</p></div><div><h3>Forme, rythme et transposition</h3><p>AABA : quatre sections de huit mesures.<br>Deux triolets de noires : quatre temps.<br>Liaison : prolonger ; silence : interrompre.<br>Ténor écrit → concert : noms un ton plus bas.<br>Cycle antihoraire : quartes ascendantes.</p></div></div><h3>Dix questions de révision</h3><ol>'+''.join('<li>'+q+'</li>' for q in ['Pourquoi un instrument en Si♭ peut-il jouer en Mi♭ majeur écrit ?','Quelle différence sépare degré et intervalle ?','Pourquoi relève-t-on la septième du mineur harmonique ?','Quelles notes distinguent C7, Cmaj7 et Cm7 ?','Comment prouver qu’une suite est un II–V–I majeur ?','Pourquoi Dm7♭5 G7 Cm7 ne relève-t-il pas d’une seule gamme harmonique inchangée ?','Quel rôle joue La♭ dans Fm7 puis B♭7 ?','Que peuvent annoncer les fins différentes des A ?','Combien dure une noire de triolet et que change une liaison ?','Comment transposer une cadence au ténor en conservant fonctions et qualités ?'])+'</ol><h3>Résumé final</h3><p>Nommer les notes. Construire les accords. Vérifier les fonctions. Entendre les résolutions majeures et mineures. Lire la forme avant de remplir la phrase. Compter les liaisons et les silences. Jouer les notes écrites avec un accompagnement dans les sons réels correspondants.</p>'
        if sid=='sources':text+='<p class="sources">Transposition : <a href="https://www.yamaha.com/en/musical_instrument_guide/saxophone/play/play003.html">Yamaha, le saxophone comme instrument transpositeur</a>. Étude comparative : <a href="https://www.jazzguitar.be/blog/autumn-leaves-melody-and-solo">Dirk Laukens, Autumn Leaves</a>. La grille AABA originale du chapitre Structure est une composition pédagogique, distincte de toute transcription de standard.</p>'
        practice.append(sec(sid,title,text))
    page('pratique',practice)
    # Accueil : montrer l'ordre d'apprentissage, les prérequis et les trois volets demandés.
    cards=''.join(f'<a class="course-card {"featured" if slug in ["ii-v-i-majeur","ii-v-i-mineur"] else ""}" href="{slug}.html" data-chapter="{slug}"><span class="top"><span class="num">{num}</span><span class="pill">{tag}</span></span><h3>{title}</h3><p>{desc}</p><span class="bottom">{duration} · exercices corrigés <span aria-hidden="true">Étudier →</span></span></a>' for slug,num,title,desc,tag,duration in chapters)
    art='<div class="hero-art"><div class="art-top"><span class="eyebrow">Deux cadences à entendre</span><span class="pill">Écrit ténor Si♭</span></div><p class="mini">Mi♭ majeur écrit</p><div class="cadence"><div class="chord"><small>II · PRÉPARER</small><strong>Fm7</strong><span>Fa · La♭ · Do · Mi♭</span></div><div class="chord"><small>V · TENDRE</small><strong>B♭7</strong><span>Si♭ · Ré · Fa · La♭</span></div><div class="chord target"><small>I · RÉSOUDRE</small><strong>E♭maj7</strong><span>Mi♭ · Sol · Si♭ · Ré</span></div></div><p class="mini" style="margin-top:22px">Do mineur écrit</p><div class="cadence"><div class="chord"><small>ii · PRÉPARER</small><strong>Dm7♭5</strong><span>Ré · Fa · La♭ · Do</span></div><div class="chord"><small>V · TENDRE</small><strong>G7</strong><span>Sol · Si · Ré · Fa</span></div><div class="chord target"><small>i · RÉSOUDRE</small><strong>Cm7</strong><span>Do · Mi♭ · Sol · Si♭</span></div></div><p class="art-note">Les notes changent avec la tonalité ; les fonctions restent des repères.</p></div>'
    home='<main class="wrap" id="contenu"><section class="hero"><div><p class="eyebrow">Harmonie jazz / parcours pour saxophone ténor Si♭</p><h1>Des notes.<br>Des accords.<br><em>Le sens des morceaux.</em></h1><p class="intro">Apprendre l’harmonie pas à pas : construire les accords, entendre les II–V–I majeurs et mineurs, puis comprendre la structure d’un standard.</p><div class="actions"><a class="btn primary" href="tenor.html">Commencer le parcours →</a><a class="btn" href="body-and-soul.html">Étudier Body and Soul</a></div><p class="mini muted">13 chapitres · notes écrites pour ténor · exercices progressifs</p></div>'+art+'</section>'+call('La convention du parcours','Tous les accords et toutes les notes de travail sont écrits pour le saxophone ténor en Si♭. Les correspondances concert sont séparées. Les outils audio produisent les sons réels du ténor, une neuvième majeure sous les notes écrites.')+'<section id="parcours"><div class="section-head"><div><p class="eyebrow">Du vocabulaire à l’interprétation</p><h2>Un parcours, une progression.</h2></div><p>Lire une notion, construire les notes, jouer un exercice, puis valider le repère avant de poursuivre.</p></div><div class="cards">'+cards+'</div></section><section class="banner"><div><p class="eyebrow">Un projet continu</p><h2>Suivre la forme.<br>Faire entendre les accords.</h2><p>Un carnet et une étude AABA originale de 32 mesures s’enrichissent à chaque étape. « Body and Soul », « Autumn Leaves » et « Misty » permettent de comparer les mêmes notions dans des standards.</p><a href="pratique.html#projet">Voir les jalons du projet →</a></div><div class="steps"><div class="step"><span>01–04</span> Lire, construire les gammes et les accords.</div><div class="step"><span>05–07</span> Résoudre en majeur et en mineur, relier les voix.</div><div class="step"><span>08–09</span> Lire la structure et analyser un standard.</div><div class="step"><span>10–13</span> Développer rythme, couleurs, transposition et interprétation.</div></div></section></main>'
    (out/'index.html').write_text(shell('Un parcours d’harmonie jazz pour ténor Si♭',home,'index'))
    # Une référence de notes indépendante du lecteur, utile à la validation musicale.
    data={'instrument':'tenor-bb','notation':'written','sounding_midi_offset':-14,'scales':{k:{kind:scale(k,kind) for kind in SCALES} for k in KEYS},'cadences':{k:{mode:cadence(k,mode) for mode in ['major','minor']} for k in KEYS},'study':study}
    (out/'assets/harmony.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
